RUN npm install

# Create a test project directory
WORKDIR /test-project

# Create project structure
RUN mkdir -p App wwwroot/dist

# Create package.json
COPY <<EOF /test-project/package.json
{
  "name": "webpack-watch-test",
  "version": "1.0.0",
  "description": "Test for webpack watch issue",
  "main": "index.js",
  "scripts": {
    "build": "webpack",
    "watch": "webpack --watch"
  },
  "dependencies": {
    "react": "^15.0.0",
    "react-dom": "^15.0.0"
  },
  "devDependencies": {
    "typescript": "1.8.10",
